import {diagram} from './diagrams.js';
import{sources,usgsUrl,metrics,minerals,projects,rareEarths,technologies}from'./data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const fmt=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:2});
const link=(key,label)=>{const s=sources[key];return `<a class="source-link" href="${s.url}" target="_blank" rel="noopener">${label||s.name} ↗</a>`};
const heading=(n,title,source='')=>`<div class="section-heading"><span class="chapter">${n} / ${title}</span><span class="source-label">${source}</span></div>`;
const chips=a=>a.map(s=>`<span class="material-chip">${s}</span>`).join('');
$('#chapters').innerHTML=`
<nav class="chapter-nav" aria-label="Capítulos"><a href="#reservas">01 Reservas</a><a href="#territorio">02 Território</a><a href="#minerais">03 Minerais</a><a href="#fronteiras">04 Fronteiras</a><a href="#comparacao">05 Comparações</a><a href="#cadeia">06 Indústria</a><a href="#escolhas">07 Escolhas</a><a href="#fontes">08 Fontes</a></nav>
<section id="territorio" class="section territory">${heading('02','O QUE AINDA NÃO CONHECEMOS','SGB · BALANÇO ATÉ 2025')}<div class="split-intro"><h2>O mapa existe.<br><em>O detalhe ainda falta.</em></h2><p class="lede">O Brasil tem cerca de 8,51 milhões de km². Conhecer a geologia de um continente não é o mesmo que investigar cada sistema mineral em detalhe.</p></div><div class="mapping-layout"><div class="mapping-controls"><p class="eyebrow">MUDE A ESCALA DO OLHAR</p><div class="scale-buttons"><button data-scale="1000000">1:1.000.000<span>Visão nacional</span></button><button data-scale="250000">1:250.000<span>Visão regional</span></button><button class="active" data-scale="100000">1:100.000<span>Mais detalhe</span></button></div><p id="scale-explainer"></p><div id="mapping-numbers" aria-live="polite"></div><p class="note">Percentuais arredondados do balanço até 2025, publicado no Panorama SGB 2026 (p. 9). Não representam a cobertura de 2026. Áreas ilustrativas calculadas sobre 8,51 milhões de km², sem precisão cadastral.</p>${link('panorama')} · ${link('ibge')}</div><div class="waffle-panel"><div class="waffle-heading"><span>BRASIL / 100 PARTES DO TERRITÓRIO</span><span id="coverage-value"></span></div><div id="coverage-waffle" role="img"></div><p class="note"><span class="legend-square"></span> Mapeado na escala selecionada <span class="legend-square empty"></span> Sem essa cobertura no balanço</p><p class="note">Diagrama proporcional. Os quadrados não indicam localizações geográficas.</p></div></div><details class="source-map"><summary>Ver a distribuição geográfica real publicada pelo SGB</summary><figure><img loading="lazy" src="assets/sgb-coverage-2025.png" alt="Mapa do SGB com cobertura até 2025 nas escalas 1:250.000 e 1:100.000, áreas em andamento e planejadas, identificadas na legenda."><figcaption>Panorama SGB 2026, figura 4.1, p. 9 (página 11 do PDF). Áreas planejadas ou em andamento não são cobertura concluída. Reprodução da cartografia original, com legenda preservada. ${link('panorama','Abrir documento original')}</figcaption></figure></details><div class="comparison-note"><h3>Brasil × China: quem conhece melhor o próprio subsolo?</h3><div class="table-scroll"><table><caption>Escalas de mapeamento: comparação metodológica, sem ranking</caption><thead><tr><th>Escala / referência</th><th>Brasil</th><th>China</th></tr></thead><tbody><tr><th>Território aproximado</th><td>8,51 milhões km²</td><td>9,6 milhões km²</td></tr><tr><th>1:250.000 · regional</th><td>50% · balanço até 2025</td><td>Percentual contemporâneo não confirmado</td></tr><tr><th>1:100.000 · detalhe</th><td>28% · balanço até 2025</td><td>Sem série equivalente nesta seleção</td></tr><tr><th>1:50.000 · maior detalhe</th><td>Sem total nacional validado nesta seleção</td><td>14 mil km² levantados em 2024 em áreas prioritárias¹</td></tr></tbody></table></div><p class="note">¹ Área levantada em um ano, não cobertura acumulada. Não comparamos 1:100.000 com 1:50.000 como se fossem equivalentes. Estes dados não permitem declarar qual país tem mais território “desconhecido”. ${link('china')} · ${link('china2024')} · ${link('chinaArea')}</p></div><div class="amazon-story"><div><span class="eyebrow">A GRANDE INCÓGNITA GEOLÓGICA</span><h2>Amazônia.</h2><p class="lede">Conhecer não é uma autorização para minerar.</p></div><div><p>Distâncias enormes, floresta densa, rochas profundamente alteradas e acesso limitado dificultam o trabalho de campo. O mapa do SGB acima mostra lacunas no interior amazônico; não extrapolamos os percentuais nacionais para a Amazônia.</p><div class="method-grid"><div><b>01 / Sensoriamento remoto</b><span>Observa a superfície e padrões da paisagem.</span></div><div><b>02 / Aerogeofísica</b><span>Mede propriedades físicas que ajudam a interpretar estruturas.</span></div><div><b>03 / Geoquímica e campo</b><span>Testa hipóteses com amostras e observações geológicas.</span></div></div><p>Essas técnicas apoiam planejamento territorial e proteção ambiental. Uma anomalia não é uma jazida. Terras indígenas, unidades de conservação e direitos das comunidades precisam orientar as decisões.</p><p class="note">Não foi confirmado um percentual atualizado de cobertura exclusivo da Amazônia nas fontes selecionadas. ${link('amazon')} · ${link('sgb')}</p></div></div><div class="statement">Conhecimento geológico <span>≠</span> mineração automática.</div></section>
<section id="minerais" class="section minerals-section">${heading('03','OS ELEMENTOS DO FUTURO','SELECIONE UM MATERIAL')}<div class="split-intro"><h2>Muitos minerais.<br><em>Inúmeras conexões.</em></h2><p class="lede">Da resistência do aço à memória de um computador, materiais brasileiros podem participar de cadeias muito diferentes. Explore aplicações, produção e limites dos dados.</p></div><div class="filter-row" aria-label="Filtrar minerais">${['Todos','Energia','Magnetismo','Estrutura','Tecnologia'].map((t,i)=>`<button data-mineral-filter="${t}" class="${i?'':'active'}" aria-pressed="${!i}">${t}</button>`).join('')}</div><div id="mineral-grid" class="mineral-grid"></div><p class="note">Seleção temática inspirada na tabela periódica. ETR representa uma família; grafita e bauxita representam materiais minerais. Produção: 2025 estimada, salvo indicação. Detalhes e fontes em cada ficha.</p><div class="niobium-feature"><div class="niobium-number"><span>Nb</span><strong>92,9<small>%</small></strong><p>da produção mundial de nióbio<br>em 2025, estimada pelo USGS.</p></div><div><span class="eyebrow">UMA VANTAGEM CONCRETA</span><h2>O exemplo extremo<br>do nióbio.</h2><div class="share-bar" role="img" aria-label="Brasil 92,9%, restante do mundo 7,1%"><span style="width:92.857%"></span></div><div class="share-legend"><span>Brasil · 104 mil t</span><span>Mundo · 112 mil t</span></div><p>Nas regiões de Araxá e Catalão, a geologia encontra uma indústria já instalada. Ferronióbio melhora aços usados em automóveis, infraestrutura e dutos; outras aplicações incluem superligas.</p><p>A vantagem não termina no metal: engenharia, desenvolvimento de materiais e fabricação de componentes ampliam o que o país pode fazer com ele.</p><p class="note">Cálculo: 104.000 ÷ 112.000 × 100 = 92,86%. Ambos os dados são estimados e arredondados. ${link('niobium')} · <a class="source-link" href="${usgsUrl('niobium')}" target="_blank" rel="noopener">USGS 2026 · nióbio ↗</a></p></div></div><div class="rare-story"><div class="split-intro"><h2>“Terras raras”<br>não é um único mineral.</h2><p>São elementos com propriedades e mercados diferentes. Para ímãs, quatro nomes merecem atenção: <strong>neodímio, praseodímio, disprósio e térbio.</strong></p></div><div class="filter-row" aria-label="Grupos de terras raras"><button data-rare-filter="all" class="active" aria-pressed="true">Todos os elementos</button><button data-rare-filter="leve" aria-pressed="false">Leves</button><button data-rare-filter="pesada" aria-pressed="false">Pesadas + ítrio</button><button data-rare-filter="magnet" aria-pressed="false">Destaques para ímãs</button></div><div id="rare-grid" class="rare-grid"></div><div id="rare-detail" class="rare-detail" aria-live="polite"></div><p class="note">Classificação didática: La–Eu, leves; Gd–Lu e Y, pesadas. Há convenções que distinguem um grupo intermediário. Escândio aparece separadamente. ${link('reeeduca')} · ${link('doe')}</p></div><div class="geology-lab"><div><span class="eyebrow">UMA ROCHA, DIFERENTES CAMINHOS</span><h2>Por que as<br>argilas iônicas importam?</h2><p>Ao longo do intemperismo, parte dos elementos liberados da rocha pode ficar adsorvida na superfície de argilas. Não é o mesmo que estar presa dentro da estrutura de um mineral.</p><div class="segmented"><button data-geology="clay" class="active" aria-pressed="true">Argilas iônicas</button><button data-geology="rock" aria-pressed="false">Rocha mineralizada</button></div><p id="geology-copy" class="geology-copy" aria-live="polite"></p>${link('reeeduca')}</div><div class="cross-section" id="cross-section" role="img" aria-label="Corte geológico esquemático: solo, argila alterada e rocha de origem"><div class="soil-layer">SOLO E INTEMPERISMO <span>↓ água e alteração</span></div><div class="clay-layer"><span>ARGILA</span><div class="clay-ions">${Array.from({length:18},(_,i)=>`<i style="--i:${i}">${['Nd','Pr','Dy','Tb'][i%4]}</i>`).join('')}</div><b>Íons adsorvidos nas superfícies</b></div><div class="rock-layer">ROCHA DE ORIGEM <span>Minerais portadores de ETR</span></div><p class="note">Corte conceitual, sem escala. Não representa um depósito específico.</p></div></div><div class="pitinga-note"><div class="mineral-pair"><span>Monazita<small>Em geral, ETR leves</small></span><span>Xenotima<small>Y + ETR pesadas</small></span></div><div><h3>Pitinga: o interesse está também na mineralogia.</h3><p>No granito Madeira, em Pitinga (AM), a xenotima ocorre associada à mineralização de estanho e outros metais. O CETEM estudou seu processamento. Interesse geológico e testes de laboratório não comprovam uma cadeia comercial de ETR em operação.</p><p class="note">Y, Dy, Er e Yb estão entre os elementos associados à xenotima. Estudos históricos não são estimativas atuais de reservas. ${link('cetem')}</p></div></div></section>
<section id="fronteiras" class="section">${heading('04','NOVAS FRONTEIRAS','FONTES DOS OPERADORES · DATAS NAS FICHAS')}<div class="split-intro"><h2>Entre a descoberta<br>e a produção.</h2><p class="lede">Um mapa de projetos também é um mapa de estágios. Pesquisa, estudos, licenciamento e investimento precisam acontecer antes da operação comercial.</p></div><div class="projects-layout"><div class="project-atlas"><div id="project-map" class="project-map"></div><div class="map-legend"><span>● Produção</span><span>◆ Desenvolvimento</span><span>▲ Viabilidade</span><span>□ Recurso</span><span>○ Ocorrência</span></div><p class="note">Símbolos em posições municipais de referência, calculadas da malha IBGE. Não são coordenadas de jazidas ou limites de concessões. Poços de Caldas agrupa três fichas.</p></div><div><label class="select-label" for="project-select">ESCOLHA UM PROJETO OU OCORRÊNCIA</label><select id="project-select">${projects.map(p=>`<option value="${p.id}">${p.name} · ${p.state}</option>`).join('')}</select><article id="project-detail" class="project-detail" aria-live="polite"></article></div></div><p class="note">Toneladas de material mineralizado não são toneladas de óxidos. TREO significa óxidos totais de terras raras; 10.000 ppm = 1%. Declarações corporativas são identificadas como tais e não endossam viabilidade econômica ou ambiental.</p></section>
<section id="comparacao" class="section comparison-section">${heading('05','TRÊS PAÍSES, DIFERENTES POSIÇÕES','USGS · EDIÇÃO 2026')}<div class="split-intro"><h2>Compare o que<br><em>é comparável.</em></h2><p class="lede">Reservas, recursos e produção respondem a perguntas distintas. Escolha um indicador para observar Brasil, China e Estados Unidos na mesma base.</p></div><div class="dashboard"><div class="dashboard-sidebar"><label class="select-label" for="metric-select">INDICADOR</label><select id="metric-select">${metrics.map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select><div class="filter-row" aria-label="Países no gráfico">${['Brasil','China','EUA'].map((c,i)=>`<button data-country="${i}" class="active" aria-pressed="true">${c}</button>`).join('')}</div><p class="note">A seleção de países altera só o gráfico. A tabela preserva os três valores.</p><button id="download-data" class="text-button">Baixar dados deste indicador · CSV</button></div><div><div id="dashboard-header"></div><div id="dashboard-chart" aria-live="polite"></div><div class="table-scroll"><table id="dashboard-table"></table></div><p id="dashboard-note" class="note"></p></div></div></section>
<section id="cadeia" class="section chain-section">${heading('06','DO MINERAL À TECNOLOGIA','A OPORTUNIDADE INDUSTRIAL')}<div class="chain-title"><p class="eyebrow">O SEGREDO NÃO ESTÁ APENAS NO SUBSOLO.</p><h2>Está <em>na cadeia.</em></h2><p class="lede">Separar elementos, refinar materiais e fabricar componentes exige conhecimento acumulado, energia, capital, clientes e escala.</p></div><div class="chain-flow">${['Mina','Concentração','Separação','Refino / metal','Liga','Ímã','Motor','Tecnologia'].map((s,i)=>`<button data-chain="${i}" class="${i===2?'active':''}" aria-pressed="${i===2}"><span>0${i+1}</span>${s}</button>`).join('')}</div><p id="chain-explainer" class="chain-explainer" aria-live="polite"></p><div class="china-shares"><div class="share-card"><span>TERRAS RARAS PARA ÍMÃS · 2024</span><strong>60<small>%</small></strong><p>participação chinesa na mineração</p></div><div class="share-card"><span>TERRAS RARAS PARA ÍMÃS · 2024</span><strong>91<small>%</small></strong><p>participação chinesa no refino</p></div><div class="share-card"><span>ÍMÃS PERMANENTES SINTERIZADOS · 2024</span><strong>94<small>%</small></strong><p>participação chinesa na fabricação</p></div></div><p class="note">Retrato comparável de 2024, publicado pela IEA em 2026. Não é a mesma cesta de ETR usada pelo USGS. ${link('iea')}</p><p class="revision-note"><strong>Atualização de 2025:</strong> a IEA informa que a participação do maior fornecedor no refino de terras raras caiu para 85%. Mantemos o ano junto ao número e não misturamos esse dado com a série de 2024. ${link('iea2026')}</p><div class="silicon-story"><div class="split-intro"><h2>Do quartzo<br><em>ao chip.</em></h2><div><p>O silício não é raro. Transformá-lo em um material com pureza e estrutura cristalina controladas é o desafio. Quartzo de alta pureza também pode servir aos cadinhos de fabricação; não é sinônimo de silício eletrônico.</p><p class="note">A rota abaixo representa silício cristalino; outras tecnologias solares e semicondutoras usam materiais diferentes.</p></div></div><div id="silicon-flow" class="silicon-flow">${['Quartzo / sílica','Silício metalúrgico','Polissilício purificado','Lingote monocristalino','Wafer','Célula solar / chip'].map((s,i)=>`<button data-silicon="${i}" class="${!i?'active':''}" aria-pressed="${!i}"><span>0${i+1}</span><b>${s}</b></button>`).join('')}</div><div id="silicon-detail" class="silicon-detail" aria-live="polite"></div><div class="homerun-note"><h3>Bahia: uma oportunidade específica, não uma reserva nacional.</h3><p>A Homerun reportou, para o distrito de Belmonte/Santa Maria Eterna, <strong>25,56 Mt de recursos medidos</strong> e <strong>38,34 Mt inferidos</strong>, com teor médio de 99,67% SiO₂ no relatório de abril de 2025. O documento da administração de 2026 registra avanços em direitos minerais e licenciamento.</p><p class="note">São recursos de areia silicosa de um projeto. Não comprovam produção de polissilício ou chips. A pureza da sílica não equivale à pureza do silício após processamento. ${link('homerun')}</p></div></div><div class="technology-lab"><div class="split-intro"><h2>Onde entram<br>os minerais?</h2><p class="lede">Desmonte a tecnologia. Troque a química da bateria ou o tipo de motor e veja como a lista de materiais muda.</p></div><div class="tech-tabs" aria-label="Tecnologia em destaque"><button data-tech="ev" class="active" aria-pressed="true">Veículo elétrico</button><button data-tech="battery" aria-pressed="false">Bateria</button><button data-tech="wind" aria-pressed="false">Turbina eólica</button><button data-tech="solar" aria-pressed="false">Painel solar</button></div><div class="tech-lab-inner"><div><div id="technology-controls"></div><div id="technology-diagram" class="technology-diagram"></div><p class="note">Diagramas funcionais, sem escala ou proporções de massa. Selecione um componente.</p></div><article id="technology-detail" class="technology-detail" aria-live="polite"></article></div><p class="note">Materiais e rotas: ${link('doe2023')} · ${link('doe')} · ${link('bndes')}</p></div><div class="value-story"><h3>E se o Brasil produzisse a bateria, além dos minerais?</h3><div class="value-chain">${['Minério','Concentrado','Material refinado','Material ativo','Célula','Bateria completa','Veículo / armazenamento'].map((s,i)=>`<div><span>${'$'.repeat(i+1)}</span><b>${s}</b></div>`).join('')}</div><p class="note">Ilustração qualitativa de etapas produtivas. Os símbolos não representam preços, margens, multiplicadores ou garantia de rentabilidade. Cada etapa exige investimento e pode ocorrer em países diferentes.</p></div><div class="matrix-story"><h2>Uma base mineral.<br>Muitas possibilidades.</h2><p>Selecione uma tecnologia ou um material. O destaque mostra aplicações possíveis, não uma lista universal de composição ou prova de autossuficiência brasileira.</p><div class="table-scroll" tabindex="0" aria-label="Matriz de tecnologias e materiais; role horizontalmente para explorar"><table id="technology-matrix"></table></div><p id="matrix-explainer" class="note" aria-live="polite"></p><p class="note">Síntese editorial de aplicações documentadas pelo DOE e pelas fichas de materiais do USGS. ${link('doe')} · ${link('usgs')}</p></div></section>
<section id="escolhas" class="section choices-section">${heading('07','A ESCOLHA BRASILEIRA','UM DEBATE SOBRE VALOR, DIREITOS E RESPONSABILIDADE')}<div class="split-intro"><h2>A riqueza existe.<br><em>O futuro se constrói.</em></h2><p class="lede">Soberania mineral não significa apenas extrair mais. Significa decidir como o território, o conhecimento e os benefícios entram nessa história.</p></div><div class="paths"><article><span class="eyebrow">TRAJETÓRIA CENTRADA NA EXTRAÇÃO</span><h3>Exportar a matéria-prima.</h3><ol><li>Mina</li><li>Concentrado</li><li>Porto e exportação</li><li>Refino e fabricação no exterior</li><li>Importação de tecnologia</li></ol><p>Receitas de exportação podem coexistir com dependência em materiais processados e equipamentos.</p></article><article><span class="eyebrow">TRAJETÓRIA COM MAIS ETAPAS LOCAIS</span><h3>Construir capacidade industrial.</h3><ol><li>Extração responsável</li><li>Processamento e refino no Brasil</li><li>Materiais avançados</li><li>Componentes e fabricação</li><li>Tecnologia e produtos de maior valor</li></ol><p>Exige competitividade, qualificação, pesquisa, infraestrutura e demanda. Não é um resultado automático da geologia.</p></article></div><div class="sovereignty"><h2>Soberania não<br>significa isolamento.</h2><div><p>Investimento estrangeiro, transferência de tecnologia e parcerias comerciais podem ajudar. A questão é a qualidade dos acordos e a capacidade brasileira de definir prioridades.</p><p>O país pode buscar mais valor local, empregos qualificados e pesquisa, com regras transparentes para tributos e royalties, infraestrutura, exportação, proteção ambiental e direitos das comunidades.</p><p class="note">As duas trajetórias são cenários editoriais. Não descrevem todas as empresas e não são projeções econômicas.</p></div></div><div class="environment"><span class="eyebrow">UMA CONDIÇÃO, NÃO UMA NOTA DE RODAPÉ</span><h2>Não existe soberania<br>sobre um território destruído.</h2><p class="lede">Este atlas rejeita o garimpo ilegal. Uma transição tecnológica não justifica desmatamento, violação de direitos ou passivos ambientais transferidos às próximas gerações.</p><div class="environment-grid"><article><span>01</span><h3>Água e biodiversidade</h3><p>Planejar uso e recirculação de água, proteger habitats e avaliar impactos cumulativos antes de autorizar um projeto.</p></article><article><span>02</span><h3>Rejeitos e química</h3><p>Controlar reagentes, efluentes e resíduos. Alguns minérios de ETR contêm tório ou urânio e demandam avaliação radiológica.</p></article><article><span>03</span><h3>Pessoas e direitos</h3><p>Respeitar povos indígenas e comunidades locais, com consulta apropriada, transparência e participação nas decisões.</p></article><article><span>04</span><h3>Depois da mina</h3><p>Exigir fechamento, reabilitação, garantias financeiras, rastreabilidade, monitoramento e fiscalização efetiva.</p></article></div><p class="note">Princípios editoriais para o desenvolvimento responsável; não substituem análise de um projeto ou de seu licenciamento. Mineralogia e processamento: ${link('reeeduca')} · ${link('cetem')}</p></div><div class="timeline"><h2>A história continua.</h2><div class="timeline-items"><article><span>1969</span><h3>Conhecimento como infraestrutura</h3><p>Fundação da CPRM, hoje Serviço Geológico do Brasil.</p>${link('sgb')}</article><article><span>2024</span><h3>Uma nova operação</h3><p>Serra Verde inicia produção comercial em Pela Ema.</p>${link('serra')}</article><article><span>2025–2034</span><h3>Uma agenda de mapeamento</h3><p>O PlanGeo define prioridades para ampliar o conhecimento. São planos, não áreas já mapeadas.</p>${link('sgb')}</article><article><span>2026</span><h3>Novas estimativas, novas decisões</h3><p>Revisão das reservas pelo USGS e avanço dos estudos de Caldeira e Carina.</p>${link('revision')} · ${link('caldeira')}</article></div></div></section>
<section id="fontes" class="section sources-section">${heading('08','COMO ESTE ATLAS FOI FEITO','CORTE EDITORIAL · 05 OUT 2026')}<div class="split-intro"><h2>Os números têm origem.<br><em>As escolhas, contexto.</em></h2><p class="lede">Um retrato datado, construído com fontes públicas. As séries não se atualizam automaticamente; cada edição precisa rever dados, métodos e projetos.</p></div><div class="methodology"><div><h3>O que comparamos</h3><p>Produção de 2025 estimada pelo USGS e reservas publicadas no MCS 2026, versão 1.3. Cada indicador conserva unidade e definição. Recursos de empresas nunca são somados a reservas nacionais.</p></div><div><h3>O que os vazios significam</h3><p>“Não disponível” não significa zero. “W” indica informação retida pelo USGS. Percentuais de cobertura usam o balanço do SGB até 2025; dados recentes sem total comparável não substituem esse denominador.</p></div><div><h3>Confiança geológica</h3><p>Recursos medidos têm maior confiança que indicados; inferidos têm menor confiança. A conversão em reservas exige fatores econômicos, técnicos, ambientais e outros. Uma estimativa pode subir ou cair.</p></div><div><h3>Mapas e projetos</h3><p>Limites estaduais e referências municipais vêm do IBGE. Símbolos são localizadores regionais, não polígonos de lavra. Status corporativos têm data e não garantem licença, financiamento ou início de operação.</p></div></div><div class="source-directory">${Object.entries(sources).map(([k,s])=>`<a href="${s.url}" target="_blank" rel="noopener"><span>${s.name}</span><small>${s.date}</small><b aria-hidden="true">↗</b></a>`).join('')}</div><div class="sources-foot"><p>Projeto editorial independente. Sem vínculo institucional com as fontes citadas.</p><a href="data-snapshot.json" download class="text-button">Baixar base de dados · JSON</a></div></section>`;
function setPressed(selector,test){$$(selector).forEach(b=>{const active=test(b);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function renderCoverage(scale='100000'){const rates={'100000':28,'250000':50};const rate=rates[scale];setPressed('[data-scale]',b=>b.dataset.scale===scale);$('#scale-explainer').textContent=scale==='100000'?'1 cm no mapa representa 1 km no terreno. Essa escala ajuda a investigar sistemas minerais e orientar novas pesquisas.':scale==='250000'?'1 cm representa 2,5 km. Uma visão regional para reconhecer unidades geológicas e grandes estruturas.':'1 cm representa 10 km. Um mapa nacional integrado pode reunir fontes de diferentes escalas; não demonstra pesquisa detalhada uniforme.';$('#coverage-value').textContent=rate?rate+'%':'VISÃO INTEGRADA';$('#coverage-waffle').innerHTML=Array.from({length:100},(_,i)=>`<i class="${rate&&i<rate?'mapped':''} ${rate?'':'overview'}" style="transition-delay:${i*2}ms"></i>`).join('');$('#coverage-waffle').setAttribute('aria-label',rate?`${rate}% mapeado e ${100-rate}% sem cobertura nessa escala, balanço SGB até 2025.`:'Visão nacional de integração: não há percentual de levantamentos originais informado.');$('#mapping-numbers').innerHTML=rate?`<div><strong>${fmt(8.51*rate/100)}<small>milhões km²</small></strong><span>mapeados nessa escala</span></div><div><strong>${fmt(8.51*(100-rate)/100)}<small>milhões km²</small></strong><span>sem essa cobertura no balanço</span></div>`:'<div><strong>8,51<small>milhões km²</small></strong><span>dimensão aproximada do território brasileiro</span></div><p class="note">Integração nacional não equivale a mapeamento de campo de igual detalhe em todo o território.</p>'}
$$('[data-scale]').forEach(b=>b.onclick=()=>renderCoverage(b.dataset.scale));renderCoverage();
function mineralCards(filter='Todos'){$('#mineral-grid').innerHTML=minerals.filter(m=>filter==='Todos'||m.group===filter).map(m=>`<button class="mineral-tile" data-mineral="${m.symbol}"><span class="element-number">${m.number}${m.symbol==='ETR'?' elementos':''}</span><strong>${m.symbol}</strong><span>${m.name}</span><small>${m.group}</small><b aria-hidden="true">+</b></button>`).join('');$$('[data-mineral]').forEach(b=>b.onclick=()=>openMineral(b.dataset.mineral));setPressed('[data-mineral-filter]',b=>b.dataset.mineralFilter===filter)}
function openMineral(symbol){const m=minerals.find(x=>x.symbol===symbol);const url=m.source?usgsUrl(m.source):sources[m.sourceKey].url;$('#mineral-detail').innerHTML=`<span class="eyebrow">${m.group} / FICHA DO MATERIAL</span><div class="detail-title"><span>${m.symbol}</span><h2 id="dialog-title">${m.name}</h2></div><p>${m.desc}</p><dl class="fact-list"><div><dt>Por que importa</dt><dd>${m.uses}</dd></div><div><dt>${m.kind||'Reservas · edição 2026'}</dt><dd>${m.reserve}</dd></div><div><dt>Produção brasileira · 2025e</dt><dd>${m.production}</dd></div><div><dt>Produção mundial · 2025e</dt><dd>${m.world}</dd></div>${m.rank?`<div><dt>Posição</dt><dd>${m.rank}</dd></div>`:''}<div><dt>Referências geográficas</dt><dd>${m.location}</dd></div><div><dt>Transformação industrial</dt><dd>${m.processing}</dd></div></dl><p class="note">As quantidades podem representar minério, elemento ou óxido: observe a unidade. “Não harmonizada” indica que não extraímos uma série comparável.</p><a class="source-link" href="${url}" target="_blank" rel="noopener">${m.source?'USGS · MCS 2026':sources[m.sourceKey].name} ↗</a>${m.geoSource?' · '+link(m.geoSource):''} · ${link('doe','Aplicações')}`;$('#mineral-dialog').setAttribute('aria-labelledby','dialog-title');$('#mineral-dialog').showModal()}
$$('[data-mineral-filter]').forEach(b=>b.onclick=()=>mineralCards(b.dataset.mineralFilter));mineralCards();
let selectedRare='Nd';function renderRare(filter='all'){const rows=rareEarths.filter(r=>filter==='all'||(filter==='magnet'?['Nd','Pr','Dy','Tb'].includes(r[0]):r[3]===filter));$('#rare-grid').innerHTML=rows.map(r=>`<button data-rare="${r[0]}" class="${['Nd','Pr','Dy','Tb'].includes(r[0])?'magnet ':''}${r[0]===selectedRare?'active':''}" aria-pressed="${r[0]===selectedRare}"><small>${r[1]}</small><strong>${r[0]}</strong><span>${r[2]}</span></button>`).join('');if(!rows.some(r=>r[0]===selectedRare))selectedRare=rows[0][0];$$('[data-rare]').forEach(b=>b.onclick=()=>rareDetail(b.dataset.rare));setPressed('[data-rare-filter]',b=>b.dataset.rareFilter===filter);rareDetail(selectedRare)}function rareDetail(symbol){selectedRare=symbol;const r=rareEarths.find(x=>x[0]===symbol);setPressed('[data-rare]',b=>b.dataset.rare===symbol);$('#rare-detail').innerHTML=`<span>${r[0]}</span><div><h3>${r[2]}</h3><p>${r[4]}</p></div>`}$$('[data-rare-filter]').forEach(b=>b.onclick=()=>renderRare(b.dataset.rareFilter));renderRare();
function geology(type='clay'){setPressed('[data-geology]',b=>b.dataset.geology===type);$('#cross-section').classList.toggle('hard-rock',type==='rock');$('#geology-copy').textContent=type==='clay'?'Depósitos desse tipo no sul da China se tornaram importantes para ETR pesadas. No Brasil, recuperação, consumo de reagentes e impactos precisam ser testados depósito por depósito. Argila não significa mineração sem impacto.':'Em minérios de rocha, os ETR estão em minerais como monazita ou xenotima. Beneficiamento e abertura química da estrutura mineral antecedem a separação dos elementos. Teor total não é recuperação metalúrgica.'}$$('[data-geology]').forEach(b=>b.onclick=()=>geology(b.dataset.geology));geology();
export function selectProject(id){const p=projects.find(p=>p.id===id);$('#project-select').value=id;$('#project-detail').innerHTML=`<div class="status-badge">${{Produção:'●',Desenvolvimento:'◆',Viabilidade:'▲','Recurso definido':'□','Ocorrência estudada':'○'}[p.status]} ${p.status}</div><h3>${p.name}</h3><p>${p.region}</p><dl class="fact-list"><div><dt>Operador / referência</dt><dd>${p.operator}</dd></div><div><dt>Tipo de depósito</dt><dd>${p.type}</dd></div><div><dt>Estimativa / classificação</dt><dd>${p.resource}</dd></div><div><dt>Teor</dt><dd>${p.grade}</dd></div><div><dt>Elementos de interesse</dt><dd>${p.key}</dd></div></dl><p>${p.detail}</p><p class="note">Data da informação: ${p.date}. Consultado em 05/10/2026.</p>${link(p.source)}${p.extraSource?' · '+link(p.extraSource):''}`;$$('[data-project-point]').forEach(b=>{const active=b.dataset.projectPoint===id||(p.cluster&&b.dataset.projectPoint==='caldeira');b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))})}$('#project-select').onchange=e=>selectProject(e.target.value);selectProject('serra');
let countryVisible=new Set([0,1,2]),currentMetric=metrics[0];const names=['Brasil','China','Estados Unidos'];function valueText(m,i){return m.values[i]===null?(m.nodata?.[i]||'Não disponível'):fmt(m.values[i])}function dashboard(id=currentMetric.id){const m=metrics.find(x=>x.id===id);currentMetric=m;const known=m.values.filter(v=>v!==null);const max=Math.max(0,...known);$('#dashboard-header').innerHTML=`<span class="eyebrow">${m.type==='production'?'PRODUÇÃO · 2025 ESTIMADA':m.type==='reserve'?'RESERVAS · EDIÇÃO 2026':'RECURSOS · SEM SÉRIE HARMONIZADA'}</span><h3>${m.name} <small>· ${m.unit}</small></h3>`;$('#dashboard-chart').innerHTML=names.map((name,i)=>countryVisible.has(i)?`<div class="bar-row ${i===0?'featured':''}"><div class="bar-label"><span>${name}</span><strong>${valueText(m,i)}</strong></div>${m.values[i]!==null?`<div class="bar-track"><div class="bar-fill" style="width:${max?m.values[i]/max*100:0}%;${m.values[i]===0?'min-width:0':''}"></div></div>`:'<div class="missing-data">Dados diretamente comparáveis não disponíveis.</div>'}</div>`:'').join('')||'<p class="note">Selecione ao menos um país para ver o gráfico.</p>';$('#dashboard-table').innerHTML=`<caption>${m.name} · ${m.unit}</caption><thead><tr>${names.map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody><tr>${names.map((_,i)=>`<td>${valueText(m,i)}</td>`).join('')}</tr></tbody>`;$('#dashboard-note').innerHTML=`${m.note||'Valores na mesma unidade e edição. Zero é um valor informado, não uma lacuna.'} ${m.world?'Total mundial de referência: '+fmt(m.world)+' '+m.unit+'. ':''}${m.source?`<a class="source-link" href="${usgsUrl(m.source)}" target="_blank" rel="noopener">USGS 2026 · tabela original ↗</a>`:link(m.sourceKey)}`;}$('#metric-select').onchange=e=>dashboard(e.target.value);$$('[data-country]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.country);countryVisible.has(i)?countryVisible.delete(i):countryVisible.add(i);setPressed('[data-country]',b=>countryVisible.has(Number(b.dataset.country)));dashboard()});$('#download-data').onclick=()=>{const m=currentMetric;const rows=[['pais','indicador','valor','unidade','periodo','fonte','observacao'],...names.map((n,i)=>[n,m.name,m.values[i]??'',m.unit,m.type==='production'?'2025 estimado':m.type==='reserve'?'USGS 2026 v1.3':'não harmonizado',m.source?usgsUrl(m.source):sources[m.sourceKey].url,m.values[i]===null?valueText(m,i):m.note||''])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`atlas-${m.id}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};dashboard();
const chainText=['Extrair exige pesquisa, viabilidade, licenciamento e uma operação responsável. Uma reserva é o início de uma cadeia, não um produto tecnológico.','O beneficiamento concentra os minerais de interesse. Recuperação e rejeitos dependem da mineralogia e da rota escolhida.','Separar elementos quimicamente semelhantes é um dos desafios centrais das terras raras. Concentrado misto não equivale a óxidos individuais.','Óxidos purificados precisam passar por transformação e refino para produzir metais com especificações industriais.','Metais são combinados em ligas, como neodímio–ferro–boro. Composição e controle de processo definem o desempenho.','A fabricação de ímãs envolve etapas como preparação de pós, orientação magnética, consolidação e acabamento.','Motores e geradores exigem integração eletromagnética, mecânica e eletrônica. Nem todos os projetos usam terras raras.','Veículos, robôs, drones e turbinas incorporam componentes, software, engenharia e serviços. O valor também está no conhecimento.'];function chain(i){setPressed('[data-chain]',b=>Number(b.dataset.chain)===i);$('#chain-explainer').textContent=chainText[i]}$$('[data-chain]').forEach(b=>b.onclick=()=>chain(Number(b.dataset.chain)));chain(2);
const siliconText=[['O ponto de partida','Sílica (SiO₂) não é silício elementar. Mineralogia e impurezas definem quais aplicações são viáveis.','Mineração e beneficiamento presentes no Brasil.'],['Reduzir o óxido','Fornos transformam sílica em silício de grau metalúrgico. O USGS estima 180 mil toneladas de Si metálico no Brasil em 2025.','Produção nacional confirmada · USGS 2026.'],['Purificar','Rotas químicas removem impurezas para aplicações solares ou eletrônicas. Exigências variam; grau eletrônico exige controle extremo.','Etapa industrial distinta: não inferida da produção de metal.'],['Controlar o cristal','Crescimento cristalino e controle de dopagem preparam um material com propriedades eletrônicas específicas.','Tecnologia e equipamentos especializados.'],['Cortar e preparar','O lingote dá origem a lâminas, os wafers. Superfície, espessura e defeitos importam para a fabricação.','Produzir quartzo não comprova capacidade de fabricar wafers.'],['Duas rotas de fabricação','Células solares convertem luz; chips incorporam circuitos. O BNDES descreve forte dependência brasileira de módulos fotovoltaicos importados e oportunidades para fornecedores locais.','Diagnóstico industrial · BNDES, março de 2025.']];function silicon(i=0){setPressed('[data-silicon]',b=>Number(b.dataset.silicon)===i);const s=siliconText[i];$('#silicon-detail').innerHTML=`<span class="silicon-step">0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p><small>${s[2]}</small></div>`}$$('[data-silicon]').forEach(b=>b.onclick=()=>silicon(Number(b.dataset.silicon)));silicon();
let tech='ev',battery='NMC',motor='PM',wind='PM',part=0;
const techParts=()=>{const cathode=battery==='NMC'?['Li','Ni','Mn','Co']:['Li','Fe','P'];const magnet=motor==='PM'?['Nd','Pr','Dy*','Tb*']:['Cu','Al'];if(tech==='ev')return[['Carroceria',['Fe','Nb*','Al'],'Aço e alumínio podem compor a estrutura. Nióbio é adição em determinados aços, não em toda carroceria.'],['Bateria',[...cathode,'C','Cu','Al'],`Cátodo ${battery}; grafita no ânodo convencional e cobre/alumínio nos coletores. A composição exata varia por célula.`],['Motor',magnet,motor==='PM'?'Ímãs NdFeB usam Nd e Pr; Dy e Tb podem ser empregados para desempenho térmico. Nem todo ímã usa ambos.':'Motor de indução: rotor condutor de cobre ou alumínio, sem exigir ímãs de terras raras.'],['Eletrônica',['Cu','Si'],'Controle, potência e interconexões usam semicondutores e condutores; SiC também aparece em alguns projetos.']];if(tech==='battery')return[['Coletor negativo',['Cu'],'Folha de cobre conduz elétrons no lado do ânodo.'],['Ânodo',['C'],'Grafita natural, sintética ou misturas podem hospedar lítio. Alguns projetos adicionam silício.'],['Separador / eletrólito',['Li'],'Permitem transporte iônico com isolamento elétrico entre eletrodos. Não são feitos só de minerais desta seleção.'],['Cátodo',cathode,battery==='NMC'?'NMC: óxidos de níquel, manganês e cobalto com lítio. As proporções variam.':'LFP: fosfato de ferro e lítio. Não requer níquel ou cobalto no cátodo.'],['Coletor positivo',['Al'],'Folha de alumínio conduz elétrons no lado do cátodo.']];if(tech==='wind')return[['Pás',['Compósitos'],'Pás são principalmente estruturas de compósitos; não são feitas de terras raras.'],['Gerador',wind==='PM'?['Nd','Pr','Dy*','Tb*','Cu']:['Cu','Fe'],wind==='PM'?'Gerador com ímãs permanentes. Dy/Tb dependem da formulação e das exigências térmicas.':'Gerador sem ímãs permanentes de terras raras; o princípio elétrico e o projeto mecânico mudam.'],['Torre / estrutura',['Fe','Nb*'],'Aços estruturais; nióbio pode entrar como microliga em certos aços.'],['Cabos / componentes',['Cu','Al'],'Condução elétrica e componentes auxiliares. A lista depende do projeto.']];return[['Vidro e encapsulamento',['Sílica','Polímeros'],'O vidro protege a célula. Sílica do vidro não equivale ao silício eletrônico da célula.'],['Célula cristalina',['Si','Ag'],'Silício converte luz em eletricidade; prata pode integrar contatos.'],['Interconexões',['Cu'],'Conduzem a corrente entre células e para o circuito externo.'],['Moldura',['Al'],'Estrutura de suporte e proteção mecânica do módulo.']];};
function techControls(){const needBattery=['ev','battery'].includes(tech);$('#technology-controls').innerHTML=`${needBattery?`<div><label for="battery-choice">Química da bateria</label><select id="battery-choice"><option ${battery==='NMC'?'selected':''}>NMC</option><option ${battery==='LFP'?'selected':''}>LFP</option></select></div>`:''}${tech==='ev'?`<div><label for="motor-choice">Motor</label><select id="motor-choice"><option value="PM" ${motor==='PM'?'selected':''}>Ímãs permanentes</option><option value="induction" ${motor==='induction'?'selected':''}>Indução</option></select></div>`:''}${tech==='wind'?`<div><label for="wind-choice">Gerador</label><select id="wind-choice"><option value="PM" ${wind==='PM'?'selected':''}>Com ímãs permanentes</option><option value="electric" ${wind==='electric'?'selected':''}>Sem ímãs de terras raras</option></select></div>`:''}`;if($('#battery-choice'))$('#battery-choice').onchange=e=>{battery=e.target.value;renderTech()};if($('#motor-choice'))$('#motor-choice').onchange=e=>{motor=e.target.value;renderTech()};if($('#wind-choice'))$('#wind-choice').onchange=e=>{wind=e.target.value;renderTech()}}
function renderTech(){const active=document.activeElement;const focusId=active?.id;const focusPart=active?.dataset?.part;const focusTag=active?.tagName?.toLowerCase();techControls();const parts=techParts();part=Math.min(part,parts.length-1);$('#technology-diagram').className='technology-diagram diagram-'+tech;$('#technology-diagram').innerHTML=diagram(tech,part,parts)+'<div class="component-list">'+parts.map((p,i)=>`<button data-part="${i}" class="component ${part===i?'active':''}" aria-pressed="${part===i}"><span class="component-index">0${i+1}</span><strong>${p[0]}</strong><span class="component-materials">${chips(p[1])}</span></button>`).join('')+'</div>';$$('[data-part]').forEach(b=>{b.onclick=()=>{part=Number(b.dataset.part);renderTech()};if(b.tagName.toLowerCase()==='g')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();part=Number(b.dataset.part);renderTech();document.querySelector(`g[data-part="${part}"]`)?.focus()}}});const p=parts[part];$('#technology-detail').innerHTML=`<span class="eyebrow">COMPONENTE 0${part+1}</span><h3>${p[0]}</h3><div class="chip-row">${chips(p[1])}</div><p>${p[2]}</p><p class="note">* Material opcional, dependente do projeto. Presença geológica no Brasil não comprova domínio de todas as etapas industriais.</p>`;setPressed('[data-tech]',b=>b.dataset.tech===tech);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusPart!==undefined)document.querySelector(`${focusTag}[data-part="${focusPart}"]`)?.focus({preventScroll:true})}$$('[data-tech]').forEach(b=>b.onclick=()=>{tech=b.dataset.tech;part=0;renderTech()});renderTech();
const columns=['Li','Ni','Mn','C','ETR','Nb','Cu','Si','Ta','Ti','Al','Fe','U'];let selectedRow=0,selectedColumn=null;function matrix(){ const focus=document.activeElement?.dataset;const focusColumn=focus?.matrixColumn,focusRow=focus?.matrixRow;$('#technology-matrix').innerHTML=`<caption>Aplicações possíveis · seleção qualitativa de materiais</caption><thead><tr><th>Tecnologia / material</th>${columns.map(c=>`<th><button data-matrix-column="${c}" class="${selectedColumn===c?'active':''}" aria-pressed="${selectedColumn===c}" aria-label="Filtrar tecnologias que usam ${c}">${c}</button></th>`).join('')}</tr></thead><tbody>${technologies.map(([name,materials],i)=>`<tr class="${selectedRow===i?'selected':''} ${selectedColumn&&!materials.includes(selectedColumn)?'dimmed':''}"><th><button data-matrix-row="${i}" aria-pressed="${selectedRow===i}">${name}</button></th>${columns.map(c=>`<td class="${materials.includes(c)?'used':''} ${selectedColumn===c?'column-selected':''}" aria-label="${name}: ${c} ${materials.includes(c)?'uso possível':'não selecionado'}">${materials.includes(c)?'●':'·'}</td>`).join('')}</tr>`).join('')}</tbody>`;$('#matrix-explainer').textContent=selectedColumn?`${selectedColumn}: ${technologies.filter(t=>t[1].includes(selectedColumn)).map(t=>t[0]).join(', ')}. Associações possíveis; componentes e tecnologias variam.`:technologies[selectedRow][0]+': '+technologies[selectedRow][2];$$('[data-matrix-column]').forEach(b=>b.onclick=()=>{selectedColumn=selectedColumn===b.dataset.matrixColumn?null:b.dataset.matrixColumn;matrix()});$$('[data-matrix-row]').forEach(b=>b.onclick=()=>{selectedRow=Number(b.dataset.matrixRow);selectedColumn=null;matrix()});if(focusColumn)document.querySelector(`[data-matrix-column="${focusColumn}"]`)?.focus({preventScroll:true});else if(focusRow!==undefined)document.querySelector(`[data-matrix-row="${focusRow}"]`)?.focus({preventScroll:true})}matrix();
const sections=$$('main section[id]');if('IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('.chapter-nav a').forEach(a=>{a.classList.toggle('current',a.hash==='#'+e.target.id);if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-10% 0px -65% 0px'});sections.forEach(s=>obs.observe(s))}
